fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn hash(p:impl AsRef<Path>)->String{sha(&fs::read(p).unwrap())}
