let mut expected=BTreeMap::new();let mut root_rows=Vec::new();for shape in["1x2","2x2"]{let root_path=r(&format!("private/{shape}.root"));let bytes=fs::read(&root_path).unwrap();let meta=read(r(&format!("private/{shape}.root.json")));assert_eq!(hash(&root_path),meta["file_sha256"]);let trace_path=format!("/home/ubuntu/src/zopro-perf-work/g2-pack-locality176/private/{shape}-w1.json");assert_eq!(hash(&trace_path),meta["trace_sha256"]);let trace=read(&trace_path);let n=meta["root_points"].as_u64().unwrap()as usize;assert_eq!(bytes.len(),16+128*n);let norms=bytes[16..].chunks_exact(128).map(|p|p.chunks_exact(32).map(|f|{let w=std::array::from_fn(|i|u64::from_le_bytes(f[8*i..8*i+8].try_into().unwrap()));assert!(Fq::from_canonical(w).is_some());let v=Fq::from_montgomery(w);v*v}).fold(Fq::ZERO,|a,b|a+b)).collect::<Vec<_>>();let mut totals=[Fq::ZERO;8];let mut count=0usize;for row in trace["rows"].as_array().unwrap(){for component in row["batches"].as_array().unwrap(){for batch in component.as_array().unwrap(){let ordinals=batch.as_array().unwrap();for at in(0..ordinals.len()/8*8).step_by(8){for lane in 0..8{totals[lane]+=norms[ordinals[at+lane].as_u64().unwrap()as usize];}count+=1;}}}}assert_eq!(count,meta["full_groups"]);for i in 0..8{let words:[u64;4]=serde_json::from_value(meta["scalar_norm_sum_raw_words"][i].clone()).unwrap();assert_eq!(totals[i],Fq::from_montgomery(words));}for rounds in[1u64,8,256]{let fields=totals.map(|f|f*Fq::from(rounds));let bytes=fields.iter().flat_map(|f|f.to_canonical().into_iter().flat_map(u64::to_le_bytes)).collect::<Vec<_>>();expected.insert((shape.to_string(),rounds),sha(&bytes));}let log=fs::read_to_string(r(&format!("root-runs/root-{shape}/stdout.log"))).unwrap();let observed:Value=serde_json::from_str(log.trim().strip_prefix("ROOT ").unwrap()).unwrap();assert_eq!(observed["file_sha256"],meta["file_sha256"]);assert_eq!(observed["private_expected_metadata_sha256"],hash(r(&format!("private/{shape}.root.json"))));let oracle=read(format!("/home/ubuntu/src/zopro-perf-work/g2-queue-scan175/oracle-fixed-runs/oracle-{shape}/stdout.log"));assert_eq!(observed["result_sha256"],oracle["expected_canonical_result_sha256"]);root_rows.push(json!({"shape":shape,"points":n,"all_full_groups_rebuilt":count,"complete_MSM_oracle_bound":true,"independent_scalar_norm_sum_rebuilt":true}));}
let analysis=read(r("analysis.json"));let jobs=read(r("jobs.json"));let mut times=BTreeMap::<(String,String,usize),f64>::new();let mut measured=0u64;let mut primed=0u64;for j in jobs.as_array().unwrap(){let v=output(j["name"].as_str().unwrap());let shape=j["case"]["shape"].as_str().unwrap();let rounds=j["rounds"].as_u64().unwrap();let workers=j["case"]["workers"].as_u64().unwrap();assert_eq!(v["output_sha256"],expected[&(shape.to_string(),rounds)]);assert_eq!(v["independent_scalar_norm_sum_matches"],true);assert_eq!(v["timed_allocations"],0);assert_eq!(v["workers"],workers);assert_eq!(v["rounds"],rounds);assert_eq!(v["arm"],j["arm"]);let cpus=v["worker_rows"].as_array().unwrap().iter().map(|w|w["cpu"].as_u64().unwrap()).collect::<BTreeSet<_>>();assert_eq!(cpus,if workers==1{BTreeSet::from([2])}else{(0..workers).collect()});assert_eq!(v["worker_rows"].as_array().unwrap().len()as u64,workers);for w in v["worker_rows"].as_array().unwrap(){assert_eq!(w["digest"],v["output_sha256"]);assert!(w["elapsed_ns"].as_u64().unwrap()<=v["wall_ns"].as_u64().unwrap());}assert_eq!(v["root_allocation_payload_bytes"],v["root_allocation_capacity_bytes"]);assert_eq!(v["root_allocation_payload_bytes"].as_u64().unwrap(),v["root_points"].as_u64().unwrap()*128);let groups=v["full_groups_per_cycle"].as_u64().unwrap();measured+=workers*rounds*groups;primed+=workers*3*groups;if j["panel"]=="latency"{times.insert((j["case"]["name"].as_str().unwrap().to_string(),j["arm"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),v["wall_ns"].as_u64().unwrap()as f64/rounds as f64);}}assert_eq!(times.len(),270);assert_eq!(measured,analysis["measured_full8_coordinate_groups"]);assert_eq!(primed,analysis["primed_full8_coordinate_groups"]);
let mut failures=BTreeSet::new();let mut calibrations=0;for(key,v)in analysis["comparisons"].as_object().unwrap(){let p=key.split('/').collect::<Vec<_>>();let ratios=(0..15).map(|b|times[&(p[0].into(),p[1].into(),b)]/times[&(p[0].into(),p[2].into(),b)]).collect::<Vec<_>>();for(a,b)in ratios.iter().zip(v["paired"]["ratios"].as_array().unwrap()){near(*a,b.as_f64().unwrap());}let mut sorted=ratios;sorted.sort_by(f64::total_cmp);for(k,i)in[("low",3),("median",7),("high",11)]{near(sorted[i],v["paired"][k].as_f64().unwrap());}let good=sorted[11]<=1.03&&(p[1]!="off"||sorted[3]>=1./1.03);assert_eq!(good,v["passed"].as_bool().unwrap());if !good{failures.insert(key.clone());}if p[1]=="off"{assert!(good);calibrations+=1;}}
for(key,v)in analysis["aggregates"].as_object().unwrap(){let p=key.split('/').collect::<Vec<_>>();let cases=read(r("cases.json"));let selected=cases.as_array().unwrap().iter().filter(|c|p[0]=="all6"||c["workers"]==32).map(|c|c["name"].as_str().unwrap()).collect::<Vec<_>>();let ratios=(0..15).map(|b|(selected.iter().map(|c|(times[&(c.to_string(),"on".into(),b)]/times[&(c.to_string(),p[2].into(),b)]).ln()).sum::<f64>()/selected.len()as f64).exp()).collect::<Vec<_>>();for(a,b)in ratios.iter().zip(v["paired"]["ratios"].as_array().unwrap()){near(*a,b.as_f64().unwrap());}let wins=ratios.iter().filter(|x|**x<1.).count();let mut sorted=ratios;sorted.sort_by(f64::total_cmp);assert_eq!(wins,v["paired"]["wins"]);for(k,i)in[("low",3),("median",7),("high",11)]{near(sorted[i],v["paired"][k].as_f64().unwrap());}let good=sorted[11]<1.&&wins>=10;assert_eq!(good,v["passed"].as_bool().unwrap());if !good{failures.insert(format!("{key}/gain"));}}assert_eq!(calibrations,6);assert_eq!(failures.len(),16);assert_eq!(failures,analysis["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect());assert_eq!(analysis["codec_gate_passed"],false);
let mut derived=BTreeMap::new();for j in jobs.as_array().unwrap().iter().filter(|j|j["panel"]=="stat"||j["panel"]=="cycles"){let data=j["data"].as_str().unwrap();derived.insert(data.to_string(),hash(data));}for c in analysis["counters"].as_array().unwrap(){assert_eq!(c["qualified"],true);let text=fs::read_to_string(c["job"]["data"].as_str().unwrap()).unwrap();let mut events=0;for line in text.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')){let f=line.split(';').collect::<Vec<_>>();assert!(f.len()>=5);let event=f[2].trim();near(f[0].trim().parse().unwrap(),c["events"][event]["count"].as_f64().unwrap());assert!(f[3].trim().parse::<f64>().unwrap()>0.);assert_eq!(f[4].trim().parse::<f64>().unwrap(),100.);events+=1;}assert_eq!(events,4);}
let mut profile_samples=0;for p in analysis["profiles"].as_array().unwrap(){let name=p["job"].as_str().unwrap();let job=jobs.as_array().unwrap().iter().find(|j|j["name"]==name).unwrap();let meta=fs::read_to_string(r(&format!("capture/metadata-{name}/stdout.log"))).unwrap();let pid=p["pid"].as_u64().unwrap();let owners=meta.lines().filter(|l|l.contains("PERF_RECORD_MMAP")&&l.contains(job["binary"].as_str().unwrap())).map(|l|l.split_whitespace().next().unwrap().split('/').next().unwrap().parse::<u64>().unwrap()).collect::<BTreeSet<_>>();assert_eq!(owners,BTreeSet::from([pid]));let workers=p["worker_TID_CPU_pairs"].as_object().unwrap();let text=fs::read_to_string(r(&format!("capture/decode-{name}/stdout.log"))).unwrap();let mut samples=0;let mut unknown=0;let mut seen=BTreeSet::new();for l in text.lines().map(str::trim).filter(|l|!l.is_empty()&&!l.starts_with('#')){let f=l.split_whitespace().collect::<Vec<_>>();let owner=f[0].split('/').collect::<Vec<_>>();assert_eq!(owner[0].parse::<u64>().unwrap(),pid);let tid=owner[1];if let Some(cpu)=workers.get(tid){assert_eq!(f[1].trim_matches(['[',']']).parse::<u64>().unwrap(),cpu.as_u64().unwrap());seen.insert(tid.to_string());}assert_eq!(f[3],"16000000");if f[5]=="[unknown]"{unknown+=1;}samples+=1;}assert_eq!(samples,p["samples"]);assert_eq!(seen.len(),workers.len());near(unknown as f64/samples as f64,p["unknown_fraction"].as_f64().unwrap());let loss=read(r(&format!("capture/loss-{name}/stdout.log")));assert_eq!(loss["zero_lost"],true);assert!(loss["records"].as_array().unwrap().is_empty());assert!(samples>=1000&&unknown as f64/samples as f64<=0.05);assert_eq!(p["event_ok"],true);assert_eq!(p["qualified"],true);profile_samples+=samples;}
